function roleTopic(
  id: string,
  title: string,
  summary: string,
  links: SubtopicResource[],
  items: Array<[string, string, CareerSubtopic['level'], string, string, string, string[], string]>
): CareerTopicGroup {
  return {
    id,
    title,
    summary,
    subtopics: buildSubtopicsFromSpecs(id, ['Role foundations'], links, items),
  };
}

